club_players.sql:
CREATE TABLE IF NOT EXISTS club_players(
                    id TEXT PRIMARY KEY, league_id TEXT NOT NULL, team_id TEXT REFERENCES league_teams(id),
                    body TEXT NOT NULL, wage INTEGER NOT NULL, contract_end INTEGER NOT NULL);

club_receipts.sql:
CREATE TABLE IF NOT EXISTS club_receipts(
                    user_id TEXT NOT NULL, request_key TEXT NOT NULL, fingerprint TEXT NOT NULL,
                    response TEXT NOT NULL, PRIMARY KEY(user_id,request_key));

club_training_results.sql:
CREATE TABLE IF NOT EXISTS club_training_results(
                    team_id TEXT NOT NULL, local_day TEXT NOT NULL, due_at REAL NOT NULL,
                    result TEXT NOT NULL, PRIMARY KEY(team_id,local_day));

club_finance.sql:
CREATE TABLE IF NOT EXISTS club_finance(
                    id TEXT PRIMARY KEY, team_id TEXT NOT NULL, kind TEXT NOT NULL,
                    amount INTEGER NOT NULL, detail TEXT NOT NULL, at REAL NOT NULL);

club_payroll.sql:
CREATE TABLE IF NOT EXISTS club_payroll(
                    team_id TEXT NOT NULL, season INTEGER NOT NULL, matchday INTEGER NOT NULL,
                    amount INTEGER NOT NULL, PRIMARY KEY(team_id,season,matchday));

club_season_archives.sql:
CREATE TABLE IF NOT EXISTS club_season_archives(
                    league_id TEXT NOT NULL, season INTEGER NOT NULL, body TEXT NOT NULL,
                    PRIMARY KEY(league_id,season));

club_events.sql:
CREATE TABLE IF NOT EXISTS club_events(
                    id TEXT PRIMARY KEY, team_id TEXT NOT NULL, title TEXT NOT NULL,
                    body TEXT NOT NULL, at REAL NOT NULL, read_at REAL);

league_match_replays.sql:
CREATE TABLE IF NOT EXISTS league_match_replays(
                    fixture_id TEXT PRIMARY KEY, league_id TEXT NOT NULL, season INTEGER NOT NULL,
                    body BLOB NOT NULL);

friendly_careers.sql:
CREATE TABLE IF NOT EXISTS friendly_careers (
                    generation TEXT PRIMARY KEY, user_id TEXT NOT NULL, slot_number INTEGER NOT NULL,
                    team_id TEXT NOT NULL, fitness REAL NOT NULL DEFAULT 100,
                    fitness_at REAL NOT NULL, exp INTEGER NOT NULL DEFAULT 0,
                    chemistry INTEGER NOT NULL DEFAULT 50, roster TEXT NOT NULL
                );

friendly_rewards.sql:
CREATE TABLE IF NOT EXISTS friendly_rewards (
                    match_id TEXT PRIMARY KEY, generation TEXT NOT NULL, exp INTEGER NOT NULL,
                    chemistry INTEGER NOT NULL, applied_at REAL NOT NULL,
                    FOREIGN KEY(match_id) REFERENCES friendly_matches(id)
                );
